package com.hms.waitlist;
import com.hms.appointments.*; import com.hms.doctors.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/waitlist") public class WaitlistController {private final TenantRepository tenants;private final WaitlistRepository entries;private final PatientRepository patients;private final DoctorRepository doctors;public WaitlistController(TenantRepository t,WaitlistRepository e,PatientRepository p,DoctorRepository d){tenants=t;entries=e;patients=p;doctors=d;} @GetMapping public List<WaitlistEntry> list(@PathVariable String tenantSlug){return entries.findAllByTenantIdOrderByPriorityDescCreatedAtAsc(tenant(tenantSlug));} @PatchMapping("/{entryId}/status") public WaitlistEntry status(@PathVariable String tenantSlug,@PathVariable UUID entryId,@Valid @RequestBody WaitlistStatusRequest request){UUID t=tenant(tenantSlug);WaitlistEntry entry=entries.findByIdAndTenantId(entryId,t).orElseThrow(()->new IllegalArgumentException("Waitlist entry not found"));entry.updateStatus(request.status());return entries.save(entry);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
